css:
/* Drafting grid behind the chat: a 16px minor grid and a 96px major grid, drawn with gradients. */
:root:not(.dark) [data-workspace-area="conversation"] {
  background-image:
    linear-gradient(rgba(29, 78, 137, 0.11) 1px, transparent 1px),
    linear-gradient(90deg, rgba(29, 78, 137, 0.11) 1px, transparent 1px),
    linear-gradient(rgba(29, 78, 137, 0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(29, 78, 137, 0.045) 1px, transparent 1px) !important;
  background-size: 96px 96px, 96px 96px, 16px 16px, 16px 16px !important;
}
.dark [data-workspace-area="conversation"] {
  background-image:
    linear-gradient(rgba(233, 241, 248, 0.09) 1px, transparent 1px),
    linear-gradient(90deg, rgba(233, 241, 248, 0.09) 1px, transparent 1px),
    linear-gradient(rgba(233, 241, 248, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(233, 241, 248, 0.035) 1px, transparent 1px) !important;
  background-size: 96px 96px, 96px 96px, 16px 16px, 16px 16px !important;
}

/* Title-block lettering. */
[data-slot="sidebar"], [data-chat-header] { font-family: var(--font-mono, ui-monospace, monospace); letter-spacing: -0.01em; }
.chat-markdown :is(h1, h2, h3) { font-family: var(--font-mono, ui-monospace, monospace); text-transform: uppercase; letter-spacing: 0.05em; }

/* Drafting lines: near-square corners, dashed frames on code, square-capped icons. */
[data-slot="composer-host"], .chat-markdown-codeblock, [data-user-message-bubble] { border-radius: 2px !important; }
.chat-markdown-codeblock { border-style: dashed !important; }
svg.lucide { stroke-width: 1.5; stroke-linecap: square; stroke-linejoin: miter; }
:root:not(.dark) [data-user-message-bubble] { box-shadow: inset 2px 0 0 #1d4e89; }
.dark [data-user-message-bubble] { box-shadow: inset 2px 0 0 #ffd25a; }

/* Links take the accent; --info (the "Working" status) moves off the ground's own blue. */
:root:not(.dark) { --info: #2a5f9e !important; --info-foreground: #2a5f9e !important; }
.dark { --info: #8cc8ff !important; --info-foreground: #8cc8ff !important; }
:root:not(.dark) :is(.chat-markdown, [data-user-message-bubble]) a:not(.chat-markdown-file-link) { color: #1d4e89 !important; }
.dark :is(.chat-markdown, [data-user-message-bubble]) a:not(.chat-markdown-file-link) { color: #ffd25a !important; }
:root:not(.dark) ::selection { background: #cfdbe8; color: #14304f; }
.dark ::selection { background: #5b5530; color: #fffbe8; }
